/**
 * The break map: one page that shows, for each film, what was measured and
 * which moments were chosen — so that "the television knows when not to
 * interrupt" can be looked at rather than taken on trust.
 *
 *   docs/calm-points/index.html   (published with the rest of docs/)
 *
 * Generated by `npm run calm:build`, never edited: a test rebuilds it from
 * the committed measurements and sentences and fails if they differ.
 *
 * The sentence under each calm point is written by a model looking at the
 * two frames either side of the cut (describe.ts). It is for the reader of
 * this page. It chooses nothing, and the television never sees it.
 */
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { CATALOG } from '../../apps/tv-vega/src/catalog/catalog.js';
import {
  FIRST_CALM_AFTER_MS,
  MIN_CALM_SPACING_MS,
  NO_CALM_BEFORE_CREDITS_MS,
  chooseCalmPoints,
  type Measured,
} from './choose.js';

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, '..', '..');
export const BREAK_MAP_DIR = join(ROOT, 'docs', 'calm-points');
export const BREAK_MAP_FILE = join(BREAK_MAP_DIR, 'index.html');
export const FRAMES_DIR = join(BREAK_MAP_DIR, 'frames');
/** The sentences, by programme and by calm point (its position in milliseconds). */
export const DESCRIBED_FILE = join(HERE, 'described.json');

export interface PageProgramme {
  readonly title: string;
  readonly attribution: string;
  /** The catalogue's own, frame-by-frame, credits position: what the player uses. */
  readonly creditsPositionMs: number;
}

export type Described = Readonly<Record<string, Readonly<Record<string, string>>>>;

export function programmesForPage(): Record<string, PageProgramme> {
  return Object.fromEntries(CATALOG.map((p) => [p.id, { title: p.title, attribution: p.attribution, creditsPositionMs: p.creditsPositionMs }]));
}

export const frameName = (programmeId: string, atMs: number, side: 'before' | 'after'): string => `${programmeId}-${atMs}-${side}.jpg`;

const escapeHtml = (text: string): string =>
  text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/** "1:30" — minutes and seconds into the programme. */
export function clock(ms: number): string {
  const seconds = Math.floor(ms / 1000);
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
}

const seconds = (ms: number): string => `${(ms / 1000).toFixed(1)} s`;

/** One film's timeline, 1000 units wide. */
function timeline(m: Measured, creditsMs: number): string {
  const x = (ms: number): string => ((ms / m.durationMs) * 1000).toFixed(1);
  const w = (fromMs: number, toMs: number): string => (((toMs - fromMs) / m.durationMs) * 1000).toFixed(1);
  const noCalmFrom = creditsMs - NO_CALM_BEFORE_CREDITS_MS;
  const quiet = m.silences.map((s) => `<rect class="quiet" x="${x(s.startMs)}" y="14" width="${w(s.startMs, s.endMs)}" height="32"/>`).join('');
  const cuts = m.shots.slice(1).map((s) => `<line class="cut" x1="${x(s.startMs)}" x2="${x(s.startMs)}" y1="22" y2="38"/>`).join('');
  const black = m.blackFrames.map((b) => `<rect class="black" x="${x(b.startMs)}" y="14" width="${Math.max(1.5, Number(w(b.startMs, b.endMs)))}" height="32"/>`).join('');
  const points = chooseCalmPoints(m)
    .map((p) => `<g><circle class="calm" cx="${x(p.atMs)}" cy="30" r="7"/><text class="at" x="${x(p.atMs)}" y="64">${clock(p.atMs)}</text></g>`)
    .join('');
  return `<svg class="timeline" viewBox="0 0 1000 72" role="img" aria-label="Timeline of the film: cuts, quiet stretches and calm points">
  <rect class="film" x="0" y="14" width="1000" height="32" rx="4"/>
  <rect class="left-alone" x="0" y="14" width="${x(FIRST_CALM_AFTER_MS)}" height="32"/>
  <rect class="left-alone" x="${x(noCalmFrom)}" y="14" width="${w(noCalmFrom, creditsMs)}" height="32"/>
  <rect class="credits" x="${x(creditsMs)}" y="14" width="${w(creditsMs, m.durationMs)}" height="32"/>
  ${quiet}${black}${cuts}${points}
</svg>`;
}

function filmSection(m: Measured, programme: PageProgramme, described: Readonly<Record<string, string>>): string {
  const chosen = chooseCalmPoints(m);
  const sound = m.sound
    ? `Quiet means below ${m.sound.quietBelowDb} dB: fourteen under this film’s own loudness of ${m.sound.loudnessLufs} LUFS.`
    : '';
  const cards = chosen
    .map((p) => {
      const sentence = described[String(p.atMs)];
      const why = p.kind === 'after_black' ? 'After a fade through black.' : `A cut with ${seconds(p.quietMs)} of quiet around it.`;
      return `<article class="point">
  <h3>${clock(p.atMs)}</h3>
  <div class="frames">
    <figure><img src="frames/${frameName(m.programmeId, p.atMs, 'before')}" alt="The frame just before the cut" loading="lazy"/><figcaption>before</figcaption></figure>
    <figure><img src="frames/${frameName(m.programmeId, p.atMs, 'after')}" alt="The frame just after the cut" loading="lazy"/><figcaption>after</figcaption></figure>
  </div>
  <p class="why">${why}</p>
  ${sentence ? `<p class="seen">${escapeHtml(sentence)}</p>` : ''}
</article>`;
    })
    .join('\n');
  const wait = chosen[0] ? `A note sent at the start now waits ${clock(chosen[0].atMs)}, not ${clock(programme.creditsPositionMs)}.` : 'No calm point: a note waits for the credits, as before.';

  return `<section class="film">
  <h2>${escapeHtml(programme.title)}</h2>
  <p class="numbers">${m.shots.length} shots · ${m.silences.length} quiet stretches · ${m.blackFrames.length} ${m.blackFrames.length === 1 ? 'fade' : 'fades'} through black · credits at ${clock(programme.creditsPositionMs)} (Rekognition: ${m.endCreditsMs === undefined ? 'not found' : clock(m.endCreditsMs)}) · <strong>${chosen.length} calm ${chosen.length === 1 ? 'point' : 'points'}</strong></p>
  ${timeline(m, programme.creditsPositionMs)}
  <p class="note">${wait} ${sound}</p>
  <div class="points">
${cards}
  </div>
  <p class="attribution">${escapeHtml(programme.attribution)} · Creative Commons Attribution 3.0</p>
</section>`;
}

/** The whole page. Pure: the same measurements and sentences give the same text. */
export function renderBreakMap(measured: readonly Measured[], programmes: Readonly<Record<string, PageProgramme>>, described: Described): string {
  const films = [...measured]
    .sort((a, b) => a.programmeId.localeCompare(b.programmeId))
    .flatMap((m) => (programmes[m.programmeId] ? [filmSection(m, programmes[m.programmeId]!, described[m.programmeId] ?? {})] : []))
    .join('\n');

  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1"/>
<title>Calm points · Wick</title>
<meta name="description" content="Where in each film a family note may arrive without spoiling a scene: measured with Amazon Rekognition and ffmpeg, chosen by rule."/>
<link rel="icon" href="../icons/light-72.png"/>
<meta name="theme-color" content="#12100E"/>
<link rel="preconnect" href="https://fonts.googleapis.com"/>
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin/>
<link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,600&amp;family=Inter:wght@400;500;600&amp;display=swap" rel="stylesheet"/>
<link rel="stylesheet" href="../assets/site.css"/>
<style>
  .rules { list-style: none; padding: 0; margin: 28px 0 0; display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
  .rules li { background: var(--raised); border: 1px solid var(--line); border-radius: var(--radius-sm); padding: 18px 20px; color: var(--ink-dim); font-size: .94rem; }
  .rules strong { display: block; color: var(--accent); font-weight: 600; margin-bottom: 4px; }
  .legend { display: flex; flex-wrap: wrap; gap: 18px; margin: 28px 0 0; color: var(--ink-dim); font-size: .9rem; }
  .legend i { display: inline-block; width: 12px; height: 12px; border-radius: 3px; margin-right: 8px; vertical-align: -1px; }
  section.film { background: var(--raised); border: 1px solid var(--line); border-radius: var(--radius); padding: 30px; margin-top: 28px; }
  section.film h2 { font-family: var(--display); font-weight: 600; font-size: 1.8rem; letter-spacing: -.01em; margin: 0 0 6px; }
  .numbers, .note, .attribution, figcaption { color: var(--ink-dim); }
  .numbers { margin: 0; font-size: .92rem; } .numbers strong { color: var(--accent); }
  .note { margin: 6px 0 0; font-size: .95rem; }
  .timeline { width: 100%; height: auto; margin: 18px 0 8px; display: block; }
  .film { fill: #2b251e; } .left-alone { fill: #000; opacity: 0.35; } .credits { fill: #4a4136; }
  .quiet { fill: #4f7f73; opacity: 0.75; } .black { fill: #000; } .cut { stroke: #8d8375; stroke-width: 0.6; }
  .calm { fill: var(--accent); stroke: var(--ground); stroke-width: 2; } .at { fill: var(--ink); font-size: 13px; text-anchor: middle; font-family: var(--sans); }
  .points { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; margin-top: 20px; }
  .point { background: var(--ground); border: 1px solid var(--line); border-radius: 12px; padding: 18px; }
  .point h3 { font-family: var(--display); font-size: 1.4rem; font-weight: 600; margin: 0 0 12px; color: var(--accent); }
  .frames { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; } figure { margin: 0; }
  .frames img { width: 100%; border-radius: 6px; display: block; background: #000; aspect-ratio: 16 / 9; object-fit: cover; }
  figcaption { font-size: 12px; text-align: center; margin-top: 4px; letter-spacing: .04em; text-transform: uppercase; }
  .why { margin: 12px 0 0; color: var(--ink-dim); font-size: .92rem; } .seen { margin: 8px 0 0; color: var(--ink); font-style: italic; font-size: .95rem; }
  .attribution { font-size: .85rem; margin: 18px 0 0; }
  @media (max-width: 860px) { .rules { grid-template-columns: 1fr; } section.film { padding: 22px; } }
</style>
</head>
<body>
<header class="nav">
  <div class="wrap">
    <a class="brand" href="../"><img src="../icons/light-72.png" alt=""/>Wick</a>
    <div class="nav-links">
      <a class="btn sm" href="https://github.com/rogerjeasy/wick">GitHub</a>
      <a class="btn sm primary" href="https://dmaz25jvryojp.cloudfront.net/">Try the demo</a>
    </div>
  </div>
</header>
<main>
  <div class="page-head">
    <div class="wrap">
      <p class="kicker">Calm points</p>
      <h1>A note never talks over the story.</h1>
      <p class="lede">Wick never puts a family note in the middle of a scene. It used to wait for the credits. Now it also knows the moments inside a film where the picture changes and nobody is speaking, and the film waits on that cut while the note is read.</p>
      <ul class="rules">
        <li><strong>Measured</strong>Every shot, fade and the end credits by Amazon Rekognition’s video segment detection; the quiet stretches by ffmpeg, against each film’s own loudness.</li>
        <li><strong>Chosen by rule</strong>A cut inside a quiet stretch, or the end of a fade. Never in the first ${FIRST_CALM_AFTER_MS / 1000} seconds, never in the last ${NO_CALM_BEFORE_CREDITS_MS / 1000} before the credits, never two within ${MIN_CALM_SPACING_MS / 1000} seconds.</li>
        <li><strong>Described, not decided</strong>The sentence under each one is written by a model on Amazon Bedrock looking at the two frames. It chooses nothing.</li>
      </ul>
      <p class="legend"><span><i style="background:#4f7f73"></i>quiet</span><span><i style="background:#8d8375"></i>cuts</span><span><i style="background:#e8b75d"></i>calm point</span><span><i style="background:#4a4136"></i>credits</span><span><i style="background:#0a0806"></i>left alone</span></p>
    </div>
  </div>
  <div class="wrap" style="padding-bottom: 96px">
${films}
  </div>
</main>
<footer>
  <div class="wrap">
    <span>Wick · MIT licensed · Films by the Blender Foundation, CC BY 3.0</span>
    <nav aria-label="Footer"><a href="../">Home</a><a href="../privacy.html">Privacy</a><a href="../terms.html">Terms</a><a href="https://github.com/rogerjeasy/wick">GitHub</a></nav>
  </div>
</footer>
</body>
</html>
`;
}
